const projects=[
{id:'INC-001',name:'Residencial Aurora',sector:'Incorporações',budget:48,spent:24,progress:52,planned:50,days:360,status:'Saudável',owner:'Mariana Costa',risk:'Aprovações de fornecedores',action:'Manter acompanhamento semanal da obra.'},
{id:'INC-002',name:'Parque das Oliveiras',sector:'Incorporações',budget:36,spent:22,progress:48,planned:60,days:300,status:'Crítico',owner:'Rafael Almeida',risk:'Atraso nas licenças e fundações',action:'Priorizar licenças e revisar o caminho crítico.'},
{id:'LOG-001',name:'Hub Logístico Horizonte',sector:'Logística',budget:32,spent:19,progress:58,planned:62,days:240,status:'Atenção',owner:'Camila Rocha',risk:'Entrega de equipamentos',action:'Replanejar entregas com fornecedores críticos.'},
{id:'LOG-002',name:'Centro de Distribuição Sul',sector:'Logística',budget:24,spent:17,progress:75,planned:72,days:210,status:'Saudável',owner:'Pedro Santos',risk:'Integração dos sistemas',action:'Validar integração antes da operação assistida.'},
{id:'ENE-001',name:'Usina Solar Alvorada',sector:'Energia',budget:42,spent:26,progress:65,planned:63,days:330,status:'Saudável',owner:'Beatriz Lima',risk:'Conexão à rede',action:'Confirmar janela de conexão com a distribuidora.'},
{id:'ENE-002',name:'Parque Eólico Ventos do Norte',sector:'Energia',budget:58,spent:28,progress:44,planned:49,days:420,status:'Atenção',owner:'Lucas Ferreira',risk:'Transporte de aerogeradores',action:'Revisar rota e janela logística dos componentes.'}
];
const money=n=>n.toLocaleString('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:1})+' mi';
const statusClass=s=>s==='Crítico'?'Critico':s==='Atenção'?'Atencao':'';
const badge=p=>`<span class="status ${statusClass(p.status)}">● ${p.status}</span>`;
let sector='Todos os setores',query='',statusFilter='Todos os status';
const filtered=()=>projects.filter(p=>(sector==='Todos os setores'||p.sector===sector)&&(statusFilter==='Todos os status'||p.status===statusFilter)&&p.name.toLowerCase().includes(query.toLowerCase()));
const head=(eyebrow,title,description,extra='')=>`<div class="heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div>${extra}</div>`;
const filters=(search=false)=>`<div class="filters"><select id="sector" aria-label="Filtrar por setor">${['Todos os setores','Incorporações','Logística','Energia'].map(s=>`<option ${s===sector?'selected':''}>${s}</option>`).join('')}</select>${search?`<input type="search" id="search" aria-label="Buscar projeto" placeholder="Buscar projeto…" value="${query.replace(/"/g,'&quot;')}"><select id="status" aria-label="Filtrar por status">${['Todos os status','Saudável','Atenção','Crítico'].map(s=>`<option ${s===statusFilter?'selected':''}>${s}</option>`).join('')}</select>`:'<span class="tag">Outubro de 2026</span>'}<span class="stamp">● Base sintética · 6 projetos no portfólio</span></div>`;
function rows(list){return list.map(p=>`<tr><td><strong>${p.name}</strong><small>${p.id}</small></td><td>${p.sector}</td><td>${badge(p)}</td><td>${money(p.budget)}</td><td><div class="progress"><div class="bar"><i style="width:${p.progress}%"></i></div>${p.progress}%</div></td><td>${(p.progress/p.planned).toFixed(2).replace('.',',')}</td><td><button class="rowbutton" data-detail="${p.id}" aria-label="Ver detalhes de ${p.name}">↗</button></td></tr>`).join('')}
function dashboard(){const list=projects.filter(p=>sector==='Todos os setores'||p.sector===sector),budget=list.reduce((s,p)=>s+p.budget,0),spent=list.reduce((s,p)=>s+p.spent,0),progress=list.reduce((s,p)=>s+p.progress,0)/list.length;const counts=['Saudável','Atenção','Crítico'].map(s=>list.filter(p=>p.status===s).length);return head('VISÃO EXECUTIVA','O portfólio, em perspectiva.','Acompanhe o desempenho. Antecipe riscos. Direcione decisões.','<button class="button" id="export">↓ Exportar portfólio</button>')+filters()+`<div class="kpis"><div class="card"><div class="kpi-title">Projetos monitorados <span class="kpi-icon">▦</span></div><div class="value">${list.length.toString().padStart(2,'0')}</div><div class="kpi-note">${sector==='Todos os setores'?'3 setores estratégicos':sector}</div></div><div class="card"><div class="kpi-title">Orçamento do portfólio <span class="kpi-icon">↗</span></div><div class="value"><small>R$</small> ${budget} <small>mi</small></div><div class="kpi-note">${money(spent)} executados · ${Math.round(spent/budget*100)}% do total</div></div><div class="card"><div class="kpi-title">Avanço físico médio <span class="kpi-icon">◴</span></div><div class="value">${progress.toFixed(0)}<small>%</small></div><div class="kpi-note"><b>Média simples</b> dos projetos selecionados</div></div><div class="card"><div class="kpi-title">Projetos em atenção <span class="kpi-icon">⚑</span></div><div class="value">${counts[1]+counts[2]} <small>/ ${list.length}</small></div><div class="kpi-note">${counts[2]} crítico · ${counts[1]} em atenção</div></div></div><div class="grid"><section class="card"><div class="card-head"><h2>Saúde do portfólio</h2><span class="tag">Status consolidado</span></div><div class="subtitle">Uma leitura rápida de onde concentrar esforços.</div><div class="chart"><div class="donut" style="background:conic-gradient(#39775a 0 ${counts[0]/list.length*100}%,#d6b16b ${counts[0]/list.length*100}% ${(counts[0]+counts[1])/list.length*100}%,#c97b6e ${(counts[0]+counts[1])/list.length*100}% 100%)" role="img" aria-label="${counts[0]} saudáveis, ${counts[1]} em atenção, ${counts[2]} críticos"><div class="donut-center"><b>${list.length.toString().padStart(2,'0')}</b><span>projetos ativos</span></div></div><div class="legend">${['Saudável','Atenção','Crítico'].map((s,i)=>`<div class="legend-row"><span><i class="dot ${['','amber','red'][i]}"></i>${s}</span><b>${counts[i].toString().padStart(2,'0')} <span style="display:inline;color:#929b91;font-size:10px;margin-left:7px">${Math.round(counts[i]/list.length*100)}%</span></b></div>`).join('')}</div></div></section><section class="card"><div class="card-head"><h2>Investimento por setor</h2><span class="tag">R$ milhões</span></div><div class="subtitle">Distribuição do orçamento aprovado.</div>${['Incorporações','Logística','Energia'].map(s=>{const n=list.filter(p=>p.sector===s).reduce((a,p)=>a+p.budget,0);return `<div class="bar-row"><div class="bar-label"><span>${s}</span><b>${n} mi <span style="color:#99a293;font-weight:400">· ${Math.round(n/budget*100)}%</span></b></div><div class="bar"><i style="width:${n/budget*100}%"></i></div></div>`}).join('')}<div class="panel-note">Valores fictícios para exploração do protótipo.</div></section></div><section class="card table-card"><div class="table-head"><div><h2>Radar de projetos</h2><p class="subtitle">Os principais indicadores, lado a lado.</p></div><a href="#projetos">Ver todos os projetos →</a></div><table><thead><tr><th>PROJETO</th><th>SETOR</th><th>STATUS</th><th>ORÇAMENTO</th><th>AVANÇO</th><th>SPI</th><th></th></tr></thead><tbody>${rows(list)}</tbody></table></section><div class="insight"><span class="insight-icon">✧</span><div><b>Do indicador à ação</b><p>${counts[2]?`${list.find(p=>p.status==='Crítico').name} exige prioridade na revisão do cronograma.`:'Nenhum projeto crítico no setor selecionado.'} Explore cenários antes de decidir.</p></div><a href="#simulador" class="button" style="margin-left:auto;text-decoration:none">Simular cenário →</a></div>`}
function projectPage(){const list=filtered();return head('PORTFÓLIO','Projetos em movimento.','Seis iniciativas sintéticas. Três setores. Uma visão integrada.')+filters(true)+`<div class="project-grid">${list.map(p=>`<article class="card"><div class="card-head"><span class="eyebrow">${p.id}</span>${badge(p)}</div><h2>${p.name}</h2><p class="subtitle">${p.sector} · ${p.owner}</p><div class="project-metrics"><div><p class="subtitle">Orçamento</p><b>${money(p.budget)}</b></div><div><p class="subtitle">Prazo planejado</p><b>${p.days} dias</b></div></div><div class="bar-label"><span>Avanço físico</span><b>${p.progress}%</b></div><div class="bar"><i style="width:${p.progress}%"></i></div><p class="subtitle">Risco principal: ${p.risk}</p><button class="button" data-detail="${p.id}">Explorar projeto ↗</button></article>`).join('')||'<p>Nenhum projeto encontrado. Ajuste os filtros.</p>'}</div>`}
function simulator(){return head('ANÁLISE DE CENÁRIOS','Antecipe o próximo movimento.','Explore o impacto de variações no custo e no prazo de um projeto.')+`<div class="sim-grid"><section class="card"><h2>Configure seu cenário</h2><p class="subtitle">Ajuste as premissas e veja a projeção em tempo real.</p><div class="field"><label for="sim-project">Projeto de referência</label><select id="sim-project">${projects.map(p=>`<option value="${p.id}">${p.name}</option>`).join('')}</select></div><div class="field"><label for="cost">Variação no custo <b id="cost-label">+10%</b></label><input id="cost" type="range" min="-20" max="50" value="10" step="1"><div class="bar-label"><span>−20%</span><span>+50%</span></div></div><div class="field"><label for="delay">Variação no prazo <b id="delay-label">+15%</b></label><input id="delay" type="range" min="-20" max="50" value="15" step="1"><div class="bar-label"><span>−20%</span><span>+50%</span></div></div><button class="button" id="reset">↺ Restaurar cenário</button></section><section class="card result" id="sim-result" aria-live="polite"></section></div><div class="insight"><span class="insight-icon">◎</span><div><b>Uma hipótese para apoiar a conversa</b><p>O simulador aplica variações percentuais à linha de base. Não constitui previsão estatística ou recomendação financeira.</p></div></div>`}
function methodology(){return head('TRANSPARÊNCIA & GOVERNANÇA','A lógica por trás do radar.','Premissas claras para interpretar os indicadores com responsabilidade.')+`<div class="notice">O PDF da Atividade 3 não está disponível nesta sessão. Esta metodologia é provisória e precisa ser conferida com o enunciado.</div><div class="method-grid"><section class="card"><div class="eyebrow">01 · BASE DE DADOS</div><h3>Um portfólio inteiramente demonstrativo</h3><p>Seis projetos fictícios: dois de Incorporações, dois de Logística e dois de Energia. Nomes, responsáveis, valores, prazos e riscos são sintéticos. Nenhum dado representa uma empresa ou obra real.</p></section><section class="card"><div class="eyebrow">02 · VALOR AGREGADO</div><h3>Indicadores de desempenho</h3><div class="formula">EV = orçamento × avanço físico<br>PV = orçamento × avanço planejado<br>SPI = EV / PV<br>CPI = EV / custo executado</div><p>SPI e CPI abaixo de 1 sinalizam desempenho inferior à linha de base. O custo executado é informado em milhões de reais.</p></section><section class="card"><div class="eyebrow">03 · SINALIZAÇÃO</div><h3>Regras de saúde do projeto</h3><p>Utilizamos o menor valor entre SPI e CPI: saudável ≥ 0,95; atenção ≥ 0,85 e &lt; 0,95; crítico &lt; 0,85. Os status são derivados da base sintética inicial.</p><p>O avanço do portfólio é uma média simples. Orçamento e execução são somados; os filtros recalculam os indicadores.</p></section><section class="card"><div class="eyebrow">04 · SIMULAÇÃO</div><h3>Cenários determinísticos</h3><div class="formula">Custo = orçamento × (1 + variação / 100)<br>Prazo = dias × (1 + variação / 100)</div><p>A simulação não altera os projetos e não usa IA ou modelo preditivo. As variações são hipóteses escolhidas pelo usuário. Valores de prazo são arredondados para dias inteiros.</p></section></div>`}
function updateSim(){const p=projects.find(p=>p.id===document.querySelector('#sim-project').value),c=+document.querySelector('#cost').value,d=+document.querySelector('#delay').value;const sign=n=>(n>=0?'+':'')+n+'%';document.querySelector('#cost-label').textContent=sign(c);document.querySelector('#delay-label').textContent=sign(d);document.querySelector('#sim-result').innerHTML=`<div class="eyebrow" style="color:#bfdaa9">RESULTADO DO CENÁRIO</div><h3>${p.name}</h3><p class="subtitle">Custo total simulado</p><div class="result-number">${money(p.budget*(1+c/100))}</div><p>${money(Math.abs(p.budget*c/100))} ${c>=0?'acima':'abaixo'} do orçamento de ${money(p.budget)}.</p><hr><p class="subtitle">Prazo total simulado</p><div class="result-number">${Math.round(p.days*(1+d/100))} <small style="font-size:16px">dias</small></div><p>${Math.abs(Math.round(p.days*d/100))} dias ${d>=0?'a mais':'a menos'} em relação à base de ${p.days} dias.</p><hr><b>${c>20||d>20?'Impacto elevado no cenário':c>0||d>0?'Revisão de premissas sugerida':'Cenário de redução'}</b><p>Discuta viabilidade, capacidade de execução e riscos antes de rever a linha de base.</p>`}
function detail(id){const p=projects.find(p=>p.id===id);document.querySelector('#detail-content').innerHTML=`<div class="eyebrow">${p.id} · DADOS DEMONSTRATIVOS</div><h1>${p.name}</h1>${badge(p)}<p>${p.sector} · Responsável fictício: ${p.owner}</p><div class="project-metrics"><div>Orçamento<h3>${money(p.budget)}</h3></div><div>Executado<h3>${money(p.spent)}</h3></div></div><div class="project-metrics"><div>SPI<h3>${(p.progress/p.planned).toFixed(2)}</h3></div><div>CPI<h3>${(p.budget*p.progress/100/p.spent).toFixed(2)}</h3></div><div>Prazo base<h3>${p.days} dias</h3></div></div><p>Avanço físico: ${p.progress}% · Planejado: ${p.planned}%</p><h3>Risco monitorado</h3><p>${p.risk}</p><h3>Próxima ação sugerida</h3><p>${p.action}</p><p class="subtitle" style="margin:20px 0">Informações ilustrativas para avaliação do protótipo.</p>`;document.querySelector('dialog').showModal()}
function exportData(){const csv='\uFEFF'+['ID;Projeto;Setor;Status;Orçamento (R$ mi);Executado (R$ mi);Avanço (%);Prazo (dias);Dados',...projects.filter(p=>sector==='Todos os setores'||p.sector===sector).map(p=>`${p.id};${p.name};${p.sector};${p.status};${p.budget};${p.spent};${p.progress};${p.days};Demonstrativos`)].join('\n');const a=document.createElement('a'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.href=url;a.download='vanguarda-portfolio-demonstrativo.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function render(){const page=location.hash.slice(1)||'dashboard',valid=['dashboard','projetos','simulador','metodologia'].includes(page)?page:'dashboard';document.querySelectorAll('nav a').forEach(a=>{a.classList.toggle('active',a.dataset.page===valid);if(a.dataset.page===valid)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});document.querySelector('#main').innerHTML=({dashboard,projetos:projectPage,simulador:simulator,metodologia:methodology}[valid])();document.querySelector('#sector')?.addEventListener('change',e=>{sector=e.target.value;render()});document.querySelector('#status')?.addEventListener('change',e=>{statusFilter=e.target.value;render()});document.querySelector('#search')?.addEventListener('input',e=>{query=e.target.value;const start=e.target.selectionStart;render();const input=document.querySelector('#search');input.focus();input.setSelectionRange(start,start)});document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>detail(b.dataset.detail));document.querySelector('#export')?.addEventListener('click',exportData);if(valid==='simulador'){['sim-project','cost','delay'].forEach(id=>document.getElementById(id).addEventListener('input',updateSim));document.querySelector('#reset').onclick=()=>{document.querySelector('#cost').value=10;document.querySelector('#delay').value=15;updateSim()};updateSim()}}
window.addEventListener('hashchange',render);render();
